import{_ as e,o as d,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const f=JSON.parse('{"title":"日常命令 → 内部机制对照表","description":"","frontmatter":{},"headers":[],"relativePath":"mini-git-ts-course/command-map.md","filePath":"mini-git-ts-course/docs/command-map.md"}'),o={name:"mini-git-ts-course/command-map.md"};function c(i,t,h,s,n,m){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="日常命令-→-内部机制对照表" tabindex="-1">日常命令 → 内部机制对照表 <a class="header-anchor" href="#日常命令-→-内部机制对照表" aria-label="Permalink to &quot;日常命令 → 内部机制对照表&quot;">​</a></h1><p>把日常 git 命令钉回你亲手写过的机制。正本在<a href="./12-end-to-end.html">第 12 章</a>的对照表;本表补充底层命令一列,供回查。未实现的行为(如 <code>--force</code>、refspec)见<a href="./divergence.html">差异附录</a>。</p><h2 id="porcelain-日常命令" tabindex="-1">Porcelain(日常命令) <a class="header-anchor" href="#porcelain-日常命令" aria-label="Permalink to &quot;Porcelain(日常命令)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日常命令</th><th>底下发生了什么</th><th>mini-git 对应物</th><th>章节</th></tr></thead><tbody><tr><td>git init</td><td>建 .git 骨架:objects、refs/heads、HEAD</td><td><code>initRepo</code> / <code>initRepoBare</code></td><td><a href="./02-content-addressed-store.html">第 2 章</a></td></tr><tr><td>git add</td><td>文件内容做成 blob 落对象库,index 登记「路径 → 对象名」</td><td><code>writeObject</code> + <code>writeIndex</code></td><td><a href="./02-content-addressed-store.html">第 2 章</a> / <a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>git commit</td><td>暂存区清单冻结成 tree,包一层 commit 对象,当前分支引用前移</td><td><code>writeTreeFromIndex</code> → <code>commitTree</code> → <code>updateRef</code></td><td><a href="./04-commit-dag.html">第 4 章</a> / <a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>git status</td><td>工作区、暂存区、HEAD 三态两两比对</td><td><code>classifyStatus</code></td><td><a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>git diff</td><td>两份文本各摊成行,LCS 求编辑脚本,裁成 hunk</td><td><code>diffLines</code> + <code>renderUnified</code></td><td><a href="./07-line-diff.html">第 7 章</a></td></tr><tr><td>git branch</td><td>往 refs/heads 写一个 41 字节的小文件</td><td><code>updateRef</code> + <code>listBranches</code></td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>git checkout</td><td>解析目标(分支名或哈希),按其 tree 检出工作区与 index,改 HEAD</td><td><code>resolveHead</code> + <code>restoreToTree</code> + <code>attachHead</code>/<code>detachHead</code></td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>git merge</td><td>merge-base 找 base;一方可达自另一方则 fast-forward 挪引用,否则三方合并产双父提交</td><td><code>mergeBase</code>/<code>isAncestor</code> + <code>mergeCommits</code></td><td><a href="./08-merge-base.html">第 8 章</a> / <a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>git pull</td><td>先 fetch,再做一次整合(现行默认 <code>--ff-only</code>,merge 是 <code>--no-rebase</code> 一档)</td><td><code>fetchObjects</code> + 第 8-9 章判定与合并</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>git push</td><td>新尖端的可达闭包送给对端 bare 仓库;服务端量 isAncestor,非快进拒绝</td><td><code>pushObjects</code> + 服务端把关</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>git clone</td><td>引用发现、全量拉对象、检出、重建清单</td><td><code>cloneRepo</code>(握手来自第 10 章)</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>git fetch</td><td>按对端引用清单算缺失对象,搬进对象库,只前移 remote-tracking 引用</td><td><code>discoverRefs</code> + <code>fetchObjects</code></td><td><a href="./10-wire-protocol.html">第 10 章</a> / <a href="./11-sync-operations.html">第 11 章</a></td></tr></tbody></table><h2 id="plumbing-底层命令" tabindex="-1">Plumbing(底层命令) <a class="header-anchor" href="#plumbing-底层命令" aria-label="Permalink to &quot;Plumbing(底层命令)&quot;">​</a></h2><p>mini-git 全书造的正是这一层;Porcelain 是它们的组合。</p><table tabindex="0"><thead><tr><th>底层命令</th><th>做什么</th><th>mini-git 对应物</th><th>章节</th></tr></thead><tbody><tr><td>git hash-object</td><td>「类型 + 长度 + 内容」取 SHA-1,可落盘</td><td><code>hashObject</code> / <code>writeObject</code></td><td><a href="./02-content-addressed-store.html">第 2 章</a></td></tr><tr><td>git cat-file</td><td>按名字读回对象(类型或原文)</td><td><code>readObject</code></td><td><a href="./02-content-addressed-store.html">第 2 章</a></td></tr><tr><td>git write-tree</td><td>把暂存区清单拼成 tree 对象图</td><td><code>writeTree</code> / <code>writeTreeFromIndex</code></td><td><a href="./03-tree-snapshots.html">第 3 章</a> / <a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>git commit-tree</td><td>造一笔提交对象(tree、parent、身份、消息)</td><td><code>commitTree</code></td><td><a href="./04-commit-dag.html">第 4 章</a></td></tr><tr><td>git update-ref</td><td>读改一个引用文件</td><td><code>readRef</code> / <code>updateRef</code></td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>git rev-parse</td><td>把名字(HEAD、分支)解析成哈希</td><td><code>resolveHead</code></td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>git merge-base</td><td>两笔提交的最近公共祖先</td><td><code>mergeBase</code> / <code>isAncestor</code></td><td><a href="./08-merge-base.html">第 8 章</a></td></tr><tr><td>git ls-remote</td><td>列出对端引用清单(不下载任何对象)</td><td><code>discoverRefs</code></td><td><a href="./10-wire-protocol.html">第 10 章</a></td></tr><tr><td>git log</td><td>从起点沿 parent 边现算遍历</td><td><code>logWalk</code></td><td><a href="./04-commit-dag.html">第 4 章</a></td></tr></tbody></table>',7)])])}const g=e(o,[["render",c]]);export{f as __pageData,g as default};
